"""Render storage policy consumed by the deployment adapter."""
import json


def render_policy(config_json):
    config = json.loads(config_json)
    if config.get("classification") not in {"restricted", "public"}:
        raise ValueError("Explicit data classification required")
    name = config["bucket"]
    if not isinstance(name, str) or not name:
        raise ValueError("Bucket name required")
    public_read = config.get("public_read", False)
    if type(public_read) is not bool:
        raise ValueError("public_read must be boolean")
    if config["classification"] == "restricted" and public_read:
        raise ValueError("Restricted data cannot be public")
    return {"bucket": name, "read_principals": ["*"] if public_read else ["invoice-service"]}
